j2:if.script:
(function () {
	var buttonElem = $("${jvar_name}");
	var buttonIconElem = $("icon_${jvar_name}");

	var imageHealthOK = "images/icons/database.gif";
	var imageHealthNotOK = "images/icons/database.gif";
	var imageRefreshing = "images/loading_anim2.gif";

	function checkHealth(element, original, changed, loading) {
		var isValidCI = $[jvar_is_valid_ci];

		// If we've hidden the icon on form load it means that either we don't have a CI in the associated field
		// or the value in that field is invalid so we don't want to show the field until there's been a change
		if (loading $[AND] !isValidCI)
			return;

		if (changed) {
			buttonIconElem.writeAttribute("src", imageRefreshing);
			buttonElem.show();

			new Ajax.Request('/api/now/cmdbHealth/healthInfo', {
				method: 'get',
				requestHeaders: {
					'X-UserToken': window.g_ck,
					'Accept': 'application/json'
				},
				parameters: {
					"sysparm_ci_sys_ids" : changed
				},
				onSuccess: function(response) {
					displayHealthIcon(response);
				},
				onFailure: function() {
					hideHealthIcon();
				}
			});
		} else
			hideHealthIcon();
	}

	function displayHealthIcon(response){
		if (response $[AND] response.responseJSON $[AND] response.responseJSON.result $[AND] response.responseJSON.result.length != 0) {
			var result = response.responseJSON.result[0];

			$("${jvar_health_url}").value = result.health_dashboard_url;
			if (result.health_result)
				buttonIconElem.writeAttribute("src", imageHealthOK);
			else
				buttonIconElem.writeAttribute("src", imageHealthNotOK);

		} else
			hideHealthIcon();
	}

	function hideHealthIcon(){
		buttonElem.hide();
		$("${jvar_health_url}").value = "";
	}

	function openHealthDashboard() {
		var url = $("${jvar_health_url}").value;
		if (url)
			g_navigation.open(url, 'cmdb_health_dashboard_${ref}');
	}

	// Create an event handler to watch for changes on the field this "icon" is rendered next to
	var h = new GlideEventHandler('onChange_cmdb_ci_health_${ref}', checkHealth, '${ref}');
	g_event_handlers.push(h);

	// Open the health dashboard when the icon is clicked
	buttonElem.on("click", openHealthDashboard);
})();
